 \label{abstract form}
Consider the following data: 
\begin{itemize} 
\item[(i)] 
a nonconstant rational function $p(x) \in \mathbf{Q}(x) \smallsetminus \mathbf{Q}$ without pole at $x=0$, 
\item[(ii)] a formal power series 
\addtocounter{subsubsection}{1}\begin{equation} \label{normal}
x(t) \in t +  t^2 \mathbf{Q}\llbracket t \rrbracket
\end{equation}
 pulling back $p$ into an integral coefficients power series $x^* p := p(x(t)) \in \mathbf{Z} \llbracket t \rrbracket$  in the new variable $t$,
\item[(iii)]  and a holomorphic mapping $\varphi:  \overline{D(0,1)} \to \mathbf{C}$ taking $\varphi(0) = 0$ with $|\varphi'(0)| > 1$, and pulling back $p$ into a holomorphic function $\varphi^* p \in \mathcal{O}(\overline{D(0,1)})$  on some  neighborhood of the closed unit disc.
\end{itemize}
Suppose the formal power series $f_1, \ldots, f_m \in \mathbf{Q}\llbracket x \rrbracket$ are $\mathbf{Q}(p(x))$-linearly independent and satisfy the following integrality and analyticity properties like in~(ii) and~(iii):
$$
x^*f_1, \ldots, x^*f_m \in \mathbf{Z} \llbracket t \rrbracket, \quad \textrm{and} 
\quad \varphi^* f_1, \ldots, \varphi^* f_m \in \mathcal{O}(\overline{D(0,1)}).
$$
Then $f_1, \ldots, f_m \in \mathbf{Q} \llbracket x \rrbracket$ are algebraic (i.e., all $f_i \in \overline{\mathbf{Q}(x)}$), and
\addtocounter{subsubsection}{1}\begin{equation} \label{abstracted bound}
 m  \leq  e  \cdot \frac{  \int_{\mathbf{T}} \log^+{|p \circ \varphi|} \, \mu_{\mathrm{Haar}}}{\log{|\varphi'(0)|}},
  \end{equation}
where $e = 2.718\ldots$ is Euler's constant.

  \label{meromorphic form}
In the setting of Theorem~\ref{abstract form}, consider furthermore an arbitrary holomorphic function $h : \overline{D(0,1)} \to \mathbf{C}$ with $h(0) = 1$. Then
\addtocounter{subsubsection}{1}\begin{equation}  \label{meromorphic bound}
m \leq e \, \frac{ \max \big\{  \sup_{\mathbf{T}}{\log{|h|}}, \, \sup_{\mathbf{T}}{\log{|h \cdot \varphi^* p|}}  \big\}  }{\log{|\varphi'(0)|}},
\end{equation}
and $f_1, \ldots, f_m \in \overline{\mathbf{Q}(x)} \cap \mathbf{Q}\llbracket x \rrbracket$.

