  \label{lowest lexi}
Consider a function $G(\mathbf{z}) \in \mathbf{C} \llbracket \mathbf{z} \rrbracket \smallsetminus \{0\}$ holomorphic on the closed unit polydisc $\{\mathbf{z} \, : \, \max_{i=1}^d |z_i|\leq 1\}$, and let $c \, \mathbf{z^n}$ be the lexicographically minimal monomial. Then
\addtocounter{subsubsection}{1}\begin{equation} \label{lexi bound}
 \log{|c|}   \leq  \int_{\mathbf{T}^d} \log{|G|} \, \mu_{\mathrm{Haar}}. 
\end{equation}

\begin{proof}
We induct on the number of variables $d$. For $d = 1$, the bound \eqref{lexi bound} follows directly from Jensen's formula, or from the subharmonic property of the function $u(z) := \log{|z^{-n}G(z)|}$, which entails
$$
\log{|c|}  = u(0)  \leq \int_{\mathbf{T}} u \, \mu_{\mathrm{Haar}}  = \int_{\mathbf{T}} \log{|G|} \, \mu_{\mathrm{Haar}}. 
$$ 
The last equality uses that the functions $u(z) = \log{|z^{-n}G(z)|}$ and $\log{|G(z)|}$ have the same restriction on the unit circle $\mathbf{T}$.

For the induction step, we write $\mathbf{z} = (z_1, \mathbf{z}')$ and
$$
G(\mathbf{z}) = z_1^{n_1} H(\mathbf{z}), 
$$
where $H \in \mathbf{C}\llbracket \mathbf{z} \rrbracket$ is holomorphic   by our lexicographic minimality assumption. For any fixed $\mathbf{z}' \in \mathbf{T}^{d-1}$, by the same argument as the $d=1$ case above, we have
\addtocounter{subsubsection}{1}\begin{equation} \label{frozen}
\log{|H(0, \mathbf{z}')|} \leq \int_{\mathbf{T}} \log{|H(z_1, \mathbf{z}')|} \, \mu_{\mathrm{Haar}}(z_1) = \int_{\mathbf{T}} \log{|G(z_1, \mathbf{z}')|} \, \mu_{\mathrm{Haar}}(z_1).
\end{equation}
By assumption, the lexicographically minimal monomial in $H(0,\mathbf{z}') \in \mathbf{C} \llbracket \mathbf{z}' \rrbracket$ is equal to $c \, \mathbf{z}'^{\mathbf{n}'}$, where $\mathbf{n} = (n_1, \mathbf{n}')$. Therefore the induction hypothesis gives
\addtocounter{subsubsection}{1}\begin{equation}
\log{|c|}  \leq \int_{\mathbf{T}^{d-1}} \log{| H(0, \mathbf{z}') |} \, \mu_{\mathrm{Haar}} (\mathbf{z}').
\end{equation}
We complete the induction by integrating the inequality \eqref{frozen} over $\mathbf{z}' \in \mathbf{T}^{d-1}$. 
\end{proof}

