\addtocounter{subsubsection}{1}\begin{equation} \label{log derivatives are small}
m\Big(r , \frac{g'}{g}\Big) <  \log^+{\Big\{ \frac{m(R,g)}{r} \frac{R}{R-r} \Big\}}
+ \log{2} + 1/e.
\end{equation}

