\frac{g'(z)}{g(z)} = \int_{|w| = R} \frac{2w}{ ( w - z )^2 } \log{|g(w)|} \,\mu_{\mathrm{Haar}}(w), \qquad  z \in D(0,R).
\end{equation}

\begin{equation*}
\begin{split}
\int_{|z| = r} \Big| \frac{g'(z)}{g(z)} \Big| \, \mu_{\mathrm{Haar}}  
\leq 2R  \int_{|z| = r} \int_{|w| = R} |w-z|^{-2} \, \big| \log{|g(w)|} \big| \,\mu_{\mathrm{Haar}}(w) \,  \mu_{\mathrm{Haar}}(z)
\\ 
= 2R \int_{|w| = R} \Big( \int_{|z| = r} |w-z|^{-2} \, \mu_{\mathrm{Haar}}(z) \Big) \, \big| \log{|g(w)|} \big| \,\mu_{\mathrm{Haar}}(w)
\\
=\frac{2R}{R^2-r^2}   \int_{|w| = R}  \big| \log{|g(w)|} \big| \,\mu_{\mathrm{Haar}}(w)
\\
= \frac{2R}{R^2-r^2} \Big( m(R, g) + m(R,1/g) \Big) = \frac{4R \, m(R,g)}{R^2  -r^2}, 
\end{split}
\end{equation*}

