m\Big( r, \frac{F_N'}{1-F_N} \Big) + m\Big( r, \frac{1-F_N}{F_N} \Big) + N\Big( r, 1/F_N \Big)\\
\leq m\Big( r, \frac{F_N'}{1-F_N} \Big) + \log 2 + m\Big( r, \frac{1}{F_N} \Big) + N\Big( r, 1/F_N \Big)\\
=m\Big( r, \frac{(1-F_N)'}{1-F_N} \Big) + T(r, 1/F_N) + \log 2
\leq m\Big( r, \frac{(1-F_N)'}{1-F_N} \Big) + T(r, F_N) + \log 2 \\
\leq  T(r,F_N) + O \Big(   \log^+{\frac{N}{1-r} }  + \sup_{|z| = (1+r)/2}
\log^+{\log{|F_N|}} \Big),
\end{split}
\end{equation*}

\begin{equation}
\begin{split}
T(r, p \circ F_N) = m(r, p \circ F_N) \leq m\Big(r, \frac{f'}{f} \Big) 
+ m\Big(r, \frac{F_N}{F_N'}\Big) \\
\label{second main bound}
\leq T(r,F_N) + O \Big(   \log^+{\frac{N}{1-r} }  + \sup_{|z| = (1+r)/2}
\log^+{\log{|F_N|}}  \Big).
\end{split}
\end{equation}

\begin{equation} \label{Nevanlinna's Picard}
(N-1) T(r, g)  + N_{\mathrm{ram}}(r, g)   \leq \sum_{i=1}^N N(r, a_i) + O(\log{T(r,g)}) + O( \log{r} )
\end{equation}

 \label{Zbar reduction}
It is also possible to derive the $\bar{\mathbf{Z}}\llbracket q^{1/N} \rrbracket$ generalization directly from Theorem~\ref{theorem:main}, by the following argument pointed out to us
by John Voight. The absolute Galois group $\mathrm{Gal}(\bar{\mathbf{Q}}/\mathbf{Q})$ acts on the $q$-expansions of modular forms. If $f(\tau) \in O_K\llbracket q^{1/N} \rrbracket$ is a modular form on a finite index subgroup of $\mathrm{SL}_2(\mathbf{Z})$, and $\alpha_1, \ldots, \alpha_d$ is a $\mathbf{Z}$-basis of $O_K$, then $f_i(\tau) := \mathrm{Tr}_{K/\mathbf{Q}}( \alpha_i  f(\tau) ) \in \mathbf{Z}\llbracket q^{1/N} \rrbracket$ for each $i = 1,\ldots, d$. Theorem~\ref{theorem:main} gives that each $f_i(\tau)$ is modular for some congruence subgroup, say $\Gamma_i$. At this point $f(\tau)$, being a $K$-linear combination of $f_1,\ldots,f_d$, is modular for the congruence subgroup $\Gamma_1 \cap \cdots \cap \Gamma_d$.

  \label{ubd for vvmf}
Let $(F,\rho)$ be a vector-valued modular form for $\mathrm{PSL}_2(\mathbf{Z})$ of dimension~$n$ and weight~$k$. Suppose that some component function $F_j(\tau) : \mathbf{H} \to \mathbf{C}$ of $F = (F_1, \ldots, F_n) : \mathbf{H} \to \mathbf{C}^n$ has at $\tau = i \infty$
a formal Fourier expansion lying in $\mathbf{Z}\llbracket q \rrbracket = \mathbf{Z}\llbracket e^{\pi i \tau} \rrbracket$. Then that component $F_j(\tau)$ is a classical modular form of weight $k$ on a congruence subgroup of $\mathrm{SL}_2(\mathbf{Z})$.
